let stoneSelection=null;
const stoneAsset=f=>'datasets/stoneData/'+f.split('/').map(encodeURIComponent).join('/');
function stoneGallery(){return heading('溜井口石块图像数据集','stoneData · 67 张真实图像 · 1920 × 1080 · 尚无标注或模型','<button data-nav="scene/rock">进入溜井口工作台</button>')+`<section class="panel result-panel"><div class="toolbar"><label for="stoneGroup">目录分组</label><select id="stoneGroup"><option value="all">全部 67 张</option><option value="root">根目录 1 张</option><option value="s0">s0 · 10 张</option><option value="s1">s1 · 17 张</option><option value="s3">s3 · 18 张</option><option value="s3_1">s3_1 · 21 张</option></select><span class="badge" id="stoneCount">67 张</span></div><p class="note">目录名保留原始分组，不作为缺陷或石块类别标签。图片可用于样本复核；导入图片不会自动生成检测结果。</p><div id="stoneGrid" class="stone-grid"></div></section>`}
function fillStoneGrid(group='all'){let items=stoneDataset.items.filter(x=>group==='all'||x.group===group);$('#stoneCount').textContent=items.length+' 张';$('#stoneGrid').innerHTML=items.map(x=>`<button class="stone-card" data-stone="${x.file}"><img loading="lazy" src="datasets/thumbnails/${x.file.replaceAll('/','_')}" alt="溜井口样本 ${x.file}"><strong>${x.file}</strong><small>${x.width} × ${x.height} · 查看原图</small></button>`).join('')}
const beforeStoneData=dataView;dataView=function(){return `<section class="panel result-panel"><span class="badge">已导入 · 真实图片</span><h2>溜井口石块样本 stoneData</h2><p>67 张 · 1920 × 1080 · JPG · 未提供标注和模型权重</p><button class="primary" data-nav="stone-data">浏览图像数据集</button></section>`+beforeStoneData()};
const beforeStoneRender=render;render=function(){beforeStoneRender();if(activeView==='stone-data'){app.innerHTML=stoneGallery();fillStoneGrid();$('#stoneGroup').onchange=e=>fillStoneGrid(e.target.value)}if(activeView==='scene/rock'){let bar=document.createElement('div');bar.className='panel result-panel';bar.innerHTML=`<h2>已导入的真实样本</h2><div class="toolbar"><label for="stoneSample">图像选择</label><select id="stoneSample"><option value="">原资料演示样例</option>${stoneDataset.items.map(x=>`<option value="${x.file}" ${stoneSelection===x.file?'selected':''}>${x.file}</option>`).join('')}</select><button data-nav="stone-data">浏览全部 67 张</button></div><p class="note">选择导入图片后仅显示原图。该数据包没有标注和模型，不对导入图片显示资料样例的检测结果。</p>`;app.querySelector('.page-heading').after(bar);$('#stoneSample').onchange=e=>{stoneSelection=e.target.value||null;render()};if(stoneSelection){$('#sceneImage').src=stoneAsset(stoneSelection);$('#viewLabel').textContent='真实原图 · '+stoneSelection;$('#run').disabled=true;$('#run').textContent='待接入检测模型';$('#runStatus').textContent='已导入真实图像，尚无检测结果';$('#resultArea').innerHTML='';document.querySelectorAll('[data-image]').forEach(b=>b.disabled=true);$('#inputSource').disabled=true;$('#confidence').disabled=true;$('#outputFormat').disabled=true;let facts=app.querySelector('.parameter .facts');if(facts)facts.innerHTML='<div class="fact"><small>当前图像尺寸</small><strong>1920 × 1080</strong></div><div class="fact"><small>标注 / 模型</small><strong>未提供</strong></div>'}}};
window.removeEventListener('hashchange',beforeStoneRender);window.addEventListener('hashchange',render);document.addEventListener('click',e=>{let b=e.target.closest('[data-stone]');if(b){stoneSelection=b.dataset.stone;navigate('scene/rock')}});render();
